growl(){if(!AC)return;const t0=AC.currentTime;for(const det of[0,7]){const o=AC.createOscillator(),g=AC.createGain(),f=AC.createBiquadFilter(),tr=AC.createOscillator(),tg=AC.createGain();o.type='sawtooth';o.frequency.setValueAtTime(75+det,t0);o.frequency.linearRampToValueAtTime(38+det,t0+1.4);f.type='lowpass';f.frequency.value=600;tr.frequency.value=rnd(18,26);tg.gain.value=.15;tr.connect(tg);tg.connect(g.gain);g.gain.setValueAtTime(.25,t0);g.gain.linearRampToValueAtTime(0,t0+1.4);o.connect(f);f.connect(g);outN(g,.8);o.start();tr.start();o.stop(t0+1.5);tr.stop(t0+1.5)}noise(1.2,.25,500,'bandpass',.8,3)},
drink(){for(let i=0;i<4;i++){tone(rnd(180,260),.12,.18,'sine',.15,rnd(380,520),i*.22);noise(.06,.08,1500,'bandpass',.1,4)}},
pickup(){noise(.3,.3,3200,'bandpass',.2,1.5);tone(620,.1,.1,'triangle',.3,null,.05);tone(930,.14,.08,'triangle',.3,null,.14)},
knock(){const b=rnd(.8,1.3);[[180,1.6,.18],[471,1.2,.1],[893,.9,.06],[1420,.6,.04]].forEach(([f,d,v])=>tone(f*b,d,v,'sine',1));noise(.05,.25,2000,'bandpass',.8,2);if(Math.random()<.6)setTimeout(()=>SFX.knock&&[[180,1.2,.12],[471,.9,.07]].forEach(([f,d,v])=>tone(f*b,d,v,'sine',1)),rnd(250,500))},
drip(){const f=rnd(900,1700);tone(f,.09,.07,'sine',.9,f*1.8)},
