aT.knock-=dt;if(aT.knock<=0){aT.knock=rnd(7,22);SFX.knock()}aT.drip-=dt;if(aT.drip<=0){aT.drip=rnd(1.5,5);SFX.drip()}aT.far-=dt;if(aT.far<=0){aT.far=rnd(12,30);pick([SFX.slam,SFX.voices,SFX.voices,SFX.whisper])()}
