const OST={g:null,mode:'',next:0,bar:0,radioT:50};const mf=m=>440*Math.pow(2,(m-69)/12),BAR=4.8;
function ostInit(){if(OST.g||!AC)return;const comp2=AC.createDynamicsCompressor();OST.lp=AC.createBiquadFilter();OST.lp.type='lowpass';OST.lp.frequency.value=20000;OST.sfx=AC.createGain();OST.sfx.gain.value=settings.sfx;try{master.disconnect()}catch(e){}master.connect(OST.sfx);OST.sfx.connect(OST.lp);OST.lp.connect(comp2);comp2.connect(AC.destination);OST.g=AC.createGain();OST.g.gain.value=0;OST.mg=AC.createGain();OST.mg.gain.value=settings.music;OST.g.connect(OST.mg);OST.mg.connect(comp2);const w=AC.createGain();w.gain.value=.55;OST.mg.connect(w);w.connect(revIn);OST.next=AC.currentTime+.3}
function oPiano(f,t,v){for(const[m,a,d]of[[1,1,3.4],[2,.35,1.7],[3,.12,.9],[4.01,.05,.5]]){const o=AC.createOscillator(),g=AC.createGain();o.type=m===1?'triangle':'sine';o.frequency.value=f*m;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(v*a,t+.008);g.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(g);g.connect(OST.g);o.start(t);o.stop(t+d+.05)}}
function oBell(f,t,v){for(const[m,a,d]of[[1,1,3.5],[2.76,.45,2],[5.4,.2,1],[8.93,.08,.5]]){const o=AC.createOscillator(),g=AC.createGain();o.frequency.value=f*m;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(v*a,t+.004);g.gain.exponentialRampToValueAtTime(.0001,t+d);o.connect(g);g.connect(OST.g);o.start(t);o.stop(t+d+.05)}}
function oPad(f,t,dur,v,type,lp){const fl=AC.createBiquadFilter();fl.type='lowpass';fl.frequency.value=lp||700;const g=AC.createGain();g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(v,t+dur*.35);g.gain.linearRampToValueAtTime(0,t+dur);fl.connect(g);g.connect(OST.g);for(const det of[-8,0,8]){const o=AC.createOscillator();o.type=type||'sawtooth';o.frequency.value=f;o.detune.value=det;o.connect(fl);o.start(t);o.stop(t+dur+.05)}}
function oPulse(f,t,v,lp){const o=AC.createOscillator(),g=AC.createGain(),fl=AC.createBiquadFilter();o.type='square';o.frequency.value=f;fl.type='lowpass';fl.frequency.value=lp||520;g.gain.setValueAtTime(v,t);g.gain.exponentialRampToValueAtTime(.0001,t+.2);o.connect(fl);fl.connect(g);g.connect(OST.g);o.start(t);o.stop(t+.22)}
function oKick(t,v){const o=AC.createOscillator(),g=AC.createGain();o.frequency.setValueAtTime(95,t);o.frequency.exponentialRampToValueAtTime(30,t+.38);g.gain.setValueAtTime(v,t);g.gain.exponentialRampToValueAtTime(.0001,t+.55);o.connect(g);g.connect(OST.g);o.start(t);o.stop(t+.6)}
function oChoir(f,t,dur,v){const o=AC.createOscillator();o.type='sawtooth';o.frequency.value=f;const lf=AC.createOscillator(),lg=AC.createGain();lf.frequency.value=rnd(4.5,5.5);lg.gain.value=f*.012;lf.connect(lg);lg.connect(o.frequency);const g=AC.createGain();g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(v,t+dur*.4);g.gain.linearRampToValueAtTime(0,t+dur);for(const ff of[650,1080,2650]){const bp=AC.createBiquadFilter();bp.type='bandpass';bp.frequency.value=ff;bp.Q.value=8;o.connect(bp);bp.connect(g)}g.connect(OST.g);o.start(t);lf.start(t);o.stop(t+dur+.05);lf.stop(t+dur+.05)}
