let PANV=null,PATT=1;
outN=function(node,wet){let n=node;if(PANV!==null&&AC.createStereoPanner){const p=AC.createStereoPanner(),a=AC.createGain();p.pan.value=PANV;a.gain.value=PATT;node.connect(a);a.connect(p);n=p}n.connect(master);if(revIn&&wet){const g=AC.createGain();g.gain.value=wet;n.connect(g);g.connect(revIn)}};
function nearestEnemy(){let b=null,bd=1e9;for(const e of enemies){const d=Math.hypot(e.x-P.x,e.z-P.z);if(d<bd){bd=d;b=e}}return b}
