addEventListener('keydown',e=>{if(!canZoom())return;if(e.code==='Equal'||e.code==='NumpadAdd'){Zs.t=clamp(Zs.t+.25,0,1);e.preventDefault()}else if(e.code==='Minus'||e.code==='NumpadSubtract'){Zs.t=clamp(Zs.t-.25,0,1);e.preventDefault()}},true);
