const freeAt=(x,z,r)=>!colliders.some(k=>x>k.x1-r&&x<k.x2+r&&z>k.z1-r&&z<k.z2+r);
function roomSpot(d){const s=d.side;for(const[u,v]of[[3.2,0],[2.6,.8],[3.8,-.6],[2.5,-1.2],[4.2,1.1],[7.6,-.8],[8.6,.2]]){const x=s*(2+u),z=d.z+v;if(roomOf(x,z)===d&&freeAt(x,z,.35))return[x,z,-s*Math.PI/2]}return null}
const chalkT=canvasTex(256,170,(x,w,h)=>{x.clearRect(0,0,w,h);x.strokeStyle='rgba(240,240,230,.85)';x.lineWidth=3;x.lineCap='round';const eye=(cx,cy,r)=>{x.beginPath();x.ellipse(cx,cy,r,r*.55,0,0,7);x.stroke();x.beginPath();x.arc(cx,cy,r*.28,0,7);x.stroke()};eye(60,50,30);eye(190,60,22);x.strokeRect(110,70,50,85);x.beginPath();x.arc(150,115,3,0,7);x.stroke();for(let i=0;i<5;i++){x.beginPath();x.moveTo(20+i*14,150);x.lineTo(30+i*14,120);x.stroke()}x.beginPath();x.moveTo(200,120);for(let i=0;i<6;i++)x.lineTo(205+i*8,i%2?110:140);x.stroke()});
