let CUR=null;
function say(n,t,o){n.talk=Math.min(7,t.length*.045);DLG.open(NAME(n),t,o)}
const back=n=>({t:L13('oBack'),f:()=>say(n,L(TR[n.kind].p+'_again'),menu(n))});
const byeO=n=>({t:L13('oBye'),f:()=>{const t=L(TR[n.kind].p+'_bye');DLG.close();log(NAME(n)+': '+t,'#ffd9a0');n.talk=2.5;if(n.leave)leave(n)}});
function menu(n){const T=TR[n.kind],o=T.main.map(([l,g])=>({t:((n.seen||{})[g]?'\u2713 ':'')+L(l),f:()=>run(n,g)}));T.act.forEach(([l,g])=>o.push({t:L(l),f:()=>run(n,g)}));o.push(byeO(n));return o}
function removeNPC(n){if(n.g.parent)world.remove(n.g);if(n.col)colliders=colliders.filter(k=>k!==n.col);const L2=window.__npcList14();const i=L2.indexOf(n);if(i>=0)L2.splice(i,1)}
function leave(n){n.leaving=2}
function run(n,g){(n.seen=n.seen||{})[g]=1;const p=TR[n.kind].p;
if(g.startsWith('n:'))return say(n,L(g.slice(2)),[back(n)]);
if(g==='olya')return say(n,L('S_olya'),[{t:L('S_qPage'),f:()=>{if(!n.given&&ST.nextOf('C')!=null){n.given=1;ST.give('C');foundMesh('note');say(n,L('S_page'),[back(n)])}else say(n,L('S_nopage'),[back(n)])}},back(n)]);
if(g==='gift'){if(G.junk>=1){G.junk--;G.chalkT=120;log(L('S_giftLog'),'#e8e8d8');toast(L('S_giftLog'));return say(n,L('S_gift'),[back(n)])}return say(n,L('S_noGift'),[back(n)])}
if(g==='bro'){if(ST.has('A')){n.leave=1;return say(n,L('V_broA'),[byeO(n)])}return say(n,L('V_bro'),[back(n)])}
if(g==='vtrade'){if(G.batteries>=1){G.batteries--;G.ammo+=4;floatTxt([L('V_tGot')]);SFX.pickup&&SFX.pickup();return say(n,L('V_trade'),[back(n)])}return say(n,L('V_noTrade'),[back(n)])}
if(g==='short'){if(G.filters>=1){G.filters--;return say(n,L('V_short'),[{t:'\u2192',f:()=>{DLG.close();log(L('V_shortLog'),'#9fd36a');noise(1.2,.4,500,'lowpass',.6);const f=$('fade');if(f){f.style.opacity=1;setTimeout(()=>{go(Math.max(2,G.floor-ri(30,60)),'trans');f.style.opacity=0},900)}else go(Math.max(2,G.floor-ri(30,60)),'trans')}}])}return say(n,L('V_noShort'),[back(n)])}
if(g==='book')return say(n,L('M_book'),[{t:L('M_qMe'),f:()=>say(n,L('M_me'),[back(n)])},back(n)]);
if(g==='talon'){if(G.junk>=2){G.junk-=2;G.bandages++;floatTxt([L('M_tGot')]);return say(n,L('M_talon'),[back(n)])}return say(n,L('M_noTalon'),[back(n)])}
if(g==='chess'){G.chessHint=1;log(L('P_chessLog'),'#ffd9a0');return say(n,L('P_chess'),[back(n)])}
if(g==='fix'){if(G.junk>=5){G.junk-=5;world.children.slice().forEach(o=>{if(o.isMesh&&o.geometry&&o.geometry.parameters&&o.geometry.parameters.width===28&&o.geometry.parameters.height===36)world.remove(o)});if(window.__T13){window.__T13.theme=null;window.__T13.anim=[]}fogN.setHex(0x0a0c08);log(L('G_fixLog'),'#6ab0c0');return say(n,L('G_fix'),[back(n)])}return say(n,L('G_noFix'),[back(n)])}
if(g==='thread'){const a=n.kind==='galya'?n:n.twin,b=n.kind==='valya'?n:n.twin;return say(n,L('n_galya')+': '+L('W_threadR')+'\n'+L('n_valya')+': '+L('W_threadF'),[back(n)])}
if(g==='choose'){const G1=n.kind==='galya'?n:n.twin,V1=n.kind==='valya'?n:n.twin;return say(n,L('W_choose'),[{t:L('W_pickG'),f:()=>{G.filters++;G.bandages++;floatTxt([L('W_rightGot')]);if(V1)removeNPC(V1);say(G1||n,L('W_right'),[byeO(G1||n)])}},{t:L('W_pickV'),f:()=>{if(G1)removeNPC(G1);say(V1||n,L('W_wrong'),[{t:'\u2026',f:()=>{DLG.close();const v=V1||n;const x=v.g.position.x,z=v.g.position.z;removeNPC(v);if(!(cur&&cur.npc14)){const m=residentMesh();m.position.set(x,0,z);world.add(m);enemies.push({m,x,z,hp:3,kind:'resident',cd:1,t:0,speed:0})}SFX.growl&&SFX.growl();log(L('W_wrongLog'),'#d8402f')}}])}},back(n)])}
if(g==='sign'){if(!ST.has('B'))return say(n,L('R_noSign'),[back(n)]);return say(n,L('R_sign'),[{t:L('R_qYes'),f:()=>{DLG.close();ending('sis')}},{t:L('R_qNo'),f:()=>say(n,L('R_no'),[back(n)])}])}}
